-- PREPARED -- NOT APPLIED.
--
-- EG: fill missing Google Place IDs, phone numbers and websites
-- (world contact-gap export of 2026-11-04). Generated by
-- world_contact_gaps/scripts/build_contact_fill_sql.py from the reviewed
-- research in eg_contact_fill.csv (evidence and the reason per row,
-- including every value held back).
--
-- Fill-only: a value is written only where the field is NULL; nothing is
-- overwritten. Place ID: the venue's own Google record (restaurant, or lodging
-- for a hotel), within 100 m of the stored point, or 100-500 m with the
-- official domain; never a hotel's record for a named restaurant inside it;
-- no search in mainland China. Phone: MICHELIN and Google agreeing, or the
-- number printed on the venue's own site; for a restaurant in a hotel only its
-- own page. Website: MICHELIN's link and the Google record agreeing on the
-- domain, or a site that loads and names the venue in its title or address;
-- never a booking, aggregator or social link; tracking parameters removed.
--
-- One transaction; any failed check rolls the whole file back. Safe to
-- re-run (fill-only).

begin;
-- hotels: 8 rows (8 Place IDs, 8 phones, 6 websites)
create temp table _fill_hotel (code text primary key, name text not null, place_id text unique, phone text, website text) on commit drop;
insert into _fill_hotel values
    ('hotel_3121', 'Al Moudira Hotel', 'ChIJNfy5G0AWSRQR5RKvyI7F52s', '+20 12 23251307', 'http://www.moudira.com/'),
    ('hotel_3122', 'Casa Cook El Gouna', 'ChIJEZ5i5L5nUhQRvOcZNGdFo-w', '+20 65 3545163', 'https://www.elgouna.com/hotels/casa-cook/'),
    ('hotel_3123', 'Dusit Thani LakeView Cairo', 'ChIJL9MWLAgXWBQRkfPKEkBVMt0', '+20 2 26140000', 'https://www.dusit.com/dusitthani-lakeviewcairo/'),
    ('hotel_3124', 'Fairmont Nile City', 'ChIJxxh4BfpAWBQR_OrLU6EDfj8', '+20 2 24619494', 'https://www.fairmont.com/nile-city-cairo/?goto=fiche_hotel&code_hotel=A5E9&merchantid=seo-maps-EG-A5E9&sourceid=aw-cen'),
    ('hotel_3128', 'Giza Palace Hotel & Spa', 'ChIJ80Mf4w5aWBQRPnocTTshP6s', '+20 2 48834222', 'https://www.gizapalace.com/'),
    ('hotel_3129', 'La Maison Bleue El Gouna', 'ChIJRyx20o1mUhQRLRfR91NSYoQ', '+20 12 83591110', 'https://www.lamaison-bleue.com/'),
    ('hotel_3130', 'Mazeej Balad Boutique Hotel', 'ChIJu0ujegBBWBQRg8sKHIgFOSM', '+20 2 27731525', NULL),
    ('hotel_3133', 'The St. Regis Cairo', 'ChIJgxYKk-VAWBQRBG5FQHuJBXw', '+20 2 25979000', NULL);

do $$
declare bad text;
begin
  -- identity: each code must still be the EG row of that name
  select string_agg(f.code, ', ') into bad from _fill_hotel f
   where not exists (select 1 from public.hotels x where x.hotel_code = f.code and x.name = f.name and x.country_code = 'EG');
  if bad is not null then raise exception 'hotels: code is no longer the exported EG row: %', bad; end if;
  -- Place IDs are unique per table
  select string_agg(f.code || ' -> ' || f.place_id || ' (held by ' || x.hotel_code || ')', '; ') into bad
    from _fill_hotel f join public.hotels x on x.google_place_id = f.place_id and x.hotel_code <> f.code;
  if bad is not null then raise exception 'hotels: Place ID already used by another row: %', bad; end if;
end $$;

update public.hotels x set google_place_id = f.place_id, updated_at = now()
  from _fill_hotel f where x.hotel_code = f.code and f.place_id is not null and x.google_place_id is null;
update public.hotels x set phone = f.phone, updated_at = now()
  from _fill_hotel f where x.hotel_code = f.code and f.phone is not null and x.phone is null;
update public.hotels x set website_url = f.website, updated_at = now()
  from _fill_hotel f where x.hotel_code = f.code and f.website is not null and x.website_url is null;

commit;
